import { GameConstants } from "../game/gameConstants";
import { GameplaySettings } from "../game/gameplaySettings";
import { HitWarning } from "../drawable/hitWarning";
import { LevelConstants } from "../level/levelConstants";
import { MouseCursor } from "../gui/mouseCursor";
import { PostProcessor } from "../gui/postProcess";
import { statsTracker } from "../game/stats";
import { Utils } from "../utility/utils";
import { Spellbook } from "../item/weapon/spellbook";
import { Player } from "./player";
import { HoverText } from "../gui/hoverText";
import { Shadow } from "../drawable/shadow";
import { getOrCreateUserId, safeRecordGameStats } from "../api";
import { getDeviceInfo } from "../utility/deviceDetector";
import { VendingMachine } from "../entity/object/vendingMachine";

export class PlayerRenderer {
  private player: Player;
  private flashingFrame: number;
  private guiHeartFrame: number;
  private hurtAlpha: number;
  private _jumpY: number;
  private motionSpeed: number;
  slowMotionEnabled: boolean;
  slowMotionOverride: boolean = false;
  private jumpHeight: number;
  private hurting: boolean;
  private hurtingShield: boolean;
  drawX: number;
  drawY: number;
  drawZ: number;
  hitX: number;
  hitY: number;
  private frame: number;
  private slowMotionTickDuration: number;
  private lowHealthFrame: number;
  private flashing: boolean;
  private lightingDirectionBucket: number | null;
  // When any overlay UI is open, freeze the player's visual facing (cardinal/diagonal pose)
  // so it doesn't jitter due to mouse movement behind menus.
  private uiPoseFrozen: boolean = false;
  private frozenPoseDirection: Direction = Direction.DOWN;
  private frozenPoseAngleRad: number | null = null;
  private outlineWorkCanvas: HTMLCanvasElement | null = null;
  private outlineWorkCtx: CanvasRenderingContext2D | null = null;
  private deathButtonHoverAnims: number[] = [0, 0];

  constructor(player: Player) {
    this.player = player;
    this.jumpY = 0;
    this.flashingFrame = 0;
    this.guiHeartFrame = 0;
    this.motionSpeed = 1;
    this.hitX = 0;
    this.hitY = 0;
    this.drawX = 0;
    this.drawY = 0;
    this.drawZ = 0;
    this.hurtAlpha = 0.25;
    this.jumpHeight = 0.25;
    this.hurting = false;
    this.hurtingShield = false;
    this.slowMotionEnabled = false;
    this.slowMotionTickDuration = 0;
    this.flashing = false;
    this.lowHealthFrame = 0;
    this.frame = 0;
    this.lightingDirectionBucket = null;
  }

  hurt = () => {
    this.hurting = true;
    this.hurtAlpha = 0.25;
  };
  hurtShield = () => {
    this.hurtingShield = true;
  };

  outlineColor = () => {
    let color = "black";
    const buffed = this.player.damageBonus > 0;
    const shielded =
      this.player.inventory.getArmor() &&
      this.player.inventory.getArmor().health > 0;

    if (buffed) {
      color = GameConstants.PLAYER_DAMAGE_BUFF_COLOR;
    }
    /*
    if (shielded) {
      color = GameConstants.PLAYER_SHIELD_COLOR;
    }
    if (buffed && shielded) {
      color =
        Math.floor(this.frame) % 2 === 0
          ? GameConstants.PLAYER_DAMAGE_BUFF_COLOR
          : GameConstants.PLAYER_SHIELD_COLOR;
    }
          */
    return color;
  };

  outlineOpacity = () => {
    let opacity = 0;

    const buffed = this.player.damageBonus > 0;
    const shielded =
      this.player.inventory.getArmor() &&
      this.player.inventory.getArmor().health > 0;

    if (buffed) {
      opacity = 0.25; //Math.sin(Date.now() / 100) * 0.1 + 0.25;
    }
    /*
    if (shielded) {
      opacity = 0.25;
    }
    if (buffed && shielded) {
      opacity = 0.5;
    }
      */
    return opacity;
  };

  flash = () => {
    this.flashing = true;
  };

  disableFlash = () => {
    this.flashing = false;
  };

  beginSlowMotion = () => {
    this.slowMotionEnabled = true;
  };

  endSlowMotion = () => {
    this.slowMotionEnabled = false;
  };

  toggleSlowMotion = () => {
    this.slowMotionOverride = !this.slowMotionOverride;
    if (this.motionSpeed === 1) this.motionSpeed = 0.25;
    else this.motionSpeed = 1;
    return this.motionSpeed !== 1;
  };

  setNewDrawXY = (x: number, y: number, z: number) => {
    // Consume any "next move is a push" marker so push easing only applies to that move.
    if (this.nextMoveIsPush) {
      this.pushingMove = true;
      this.nextMoveIsPush = false;
    } else {
      this.pushingMove = false;
    }
    this.drawX += x - this.player.x;
    this.drawY += y - this.player.y;
    this.drawZ += z - this.player.z;
    if (this.pushingMove) {
      const mag = Math.max(
        Math.abs(this.drawX),
        Math.abs(this.drawY),
        Math.abs(this.drawZ),
      );
      this.pushAnimStartMag = Math.max(0.0001, mag);
    } else {
      this.pushAnimStartMag = 0;
    }
  };

  enableSlowMotion = () => {
    // Replay pacing is independent of the dual-dagger effect, which expires
    // through updateSlowMotion on the next update.
    const replaySlow = this.player.game.replayManager.isReplaying() &&
      GameplaySettings.REPLAY_SPEED === "slow";
    const slow = this.slowMotionEnabled || replaySlow;
    if (this.motionSpeed < 1 && !slow && !this.slowMotionOverride) {
      this.motionSpeed *= 1.08;
      if (this.motionSpeed >= 1) this.motionSpeed = 1;
    }
    if (slow && this.motionSpeed > 0.25 && !this.slowMotionOverride) {
      this.motionSpeed *= 0.95;
      if (this.motionSpeed < 0.25) this.motionSpeed = 0.25;
    }
  };

  updateSlowMotion = () => {
    if (this.slowMotionTickDuration > 0) this.slowMotionTickDuration -= 1;
    if (this.slowMotionTickDuration === 0) this.slowMotionEnabled = false;
  };

  getJumpOffset = (): number => {
    return this.jumpY;
  };

  /**
   * Jump offset accessor.
   * Centralizes "no hop while pushing" without needing special-case draw logic.
   */
  get jumpY(): number {
    return this.pushingMove ? 0 : this._jumpY;
  }
  set jumpY(v: number) {
    this._jumpY = v;
  }

  /**
   * Draws the player sprite to the canvas.
   * Added `ctx.save()` at the beginning and `ctx.restore()` at the end
   * to ensure canvas state is preserved.
   */
  drawPlayerSprite = (delta: number) => {
    const player = this.player;
    const anyOverlayOpen =
      Boolean(player.menu?.open) ||
      Boolean(player.settingsMenu?.open) ||
      Boolean(player.skillsMenu?.open) ||
      Boolean(player.replayMenu?.open) ||
      player.isAnyBookOpen ||
      Boolean(player.inventory?.isOpen) ||
      Boolean(player.contextMenu?.open);

    // Snapshot pose once when an overlay opens; release when all overlays close.
    if (anyOverlayOpen && !this.uiPoseFrozen) {
      this.uiPoseFrozen = true;
      this.frozenPoseDirection = player.direction;
      this.frozenPoseAngleRad =
        !GameConstants.isMobile && player.inputHandler?.mostRecentMoveInput === "mouse"
          ? player.inputHandler.mouseAngle()
          : null;
      // Context menu already snapshots mouse angle; prefer it if it exists.
      if (
        player.contextMenu?.open &&
        typeof player.frozenMouseAngleRad === "number"
      ) {
        this.frozenPoseAngleRad = player.frozenMouseAngleRad;
      }
    } else if (!anyOverlayOpen && this.uiPoseFrozen) {
      this.uiPoseFrozen = false;
      this.frozenPoseAngleRad = null;
    }

    const divingHelmet = player.inventory.divingHelmetEquipped();
    const regularHelmet = player.inventory.getHelmet();
    const needsHelmetCompositing = (divingHelmet || regularHelmet !== null) && !!Game.helmetMaskCanvas;
    const tileX = Math.floor(this.frame);
    const targetingAngle = player.rangedTargeting?.active
      ? player.rangedTargeting.getAngleRad()
      : null;
    const renderDirection = this.uiPoseFrozen
      ? this.frozenPoseDirection
      : targetingAngle !== null
        ? this.directionFromAngle(targetingAngle)
        : player.direction;
    const tileY = renderDirection * 2;

    const dX = player.x - this.drawX - this.hitX;
    const dY = player.y - 1.45 - this.drawY - this.jumpY - this.hitY - this.drawZ;
    let drawnTile = { x: tileX, y: tileY };

    // Render the player (base sprite + armor + helmet) into an offscreen layer so we can apply
    // a single composite alpha (for the hurt fade) and derive a single composite outline (for
    // the buff/garnet-ring glow) around the silhouette — instead of per-sprite outlines on each
    // armor layer. We copy the camera transform so world-coordinate draw calls land at the
    // correct screen-space pixels inside the layer.
    const mainCtx = Game.ctx;
    Game.syncPlayerLayer();
    Game.playerLayerCtx!.setTransform(1, 0, 0, 1, 0, 0);
    Game.playerLayerCtx!.clearRect(0, 0, Game.playerLayer!.width, Game.playerLayer!.height);
    Game.playerLayerCtx!.setTransform(mainCtx.getTransform());
    Game.ctx = Game.playerLayerCtx!;

    Game.ctx.save();

    if (this.drawSmear()) {
      const smearFrame = this.setSmearFrame();
      drawnTile = { x: smearFrame.x, y: smearFrame.y };
      Game.drawPlayer(
        smearFrame.x, smearFrame.y, 1, 2, dX, dY, 1, 2,
        this.shadeColor(),
      );
    } else if (!GameConstants.isMobile) {
      // While any overlay UI is open, freeze the diagonal mouse-angle pose at the moment it opened.
      const angleRad = this.uiPoseFrozen
        ? this.frozenPoseAngleRad
        : targetingAngle !== null
          ? targetingAngle
          : player.contextMenu?.open && typeof player.frozenMouseAngleRad === "number"
            ? player.frozenMouseAngleRad
            : player.inputHandler.mostRecentMoveInput === "mouse"
              ? player.inputHandler.mouseAngle()
              : null;

      const angleDeg = angleRad === null ? null : (angleRad * 180) / Math.PI;
      const isDiagonal =
        angleDeg !== null &&
        ((angleDeg > 30 && angleDeg < 60) ||
          (angleDeg > 120 && angleDeg < 150) ||
          (angleDeg > -150 && angleDeg < -120) ||
          (angleDeg > -60 && angleDeg < -30));

      if (isDiagonal && angleDeg !== null) {
        let diagonalTile = { x: 0, y: 8 };

        if (angleDeg > -150 && angleDeg <= -120) diagonalTile = { x: 2, y: 8 };
        if (angleDeg > -60 && angleDeg <= -30)   diagonalTile = { x: 3, y: 8 };
        if (angleDeg > 30 && angleDeg <= 60)     diagonalTile = { x: 1, y: 8 };
        if (angleDeg > 120 && angleDeg <= 150)   diagonalTile = { x: 0, y: 8 };

        drawnTile = { x: diagonalTile.x, y: diagonalTile.y };
        Game.drawPlayer(
          diagonalTile.x, diagonalTile.y, 1, 2, dX, dY, 1, 2,
          this.shadeColor(),
        );
      } else {
        this.frame += 0.1 * delta;
        if (this.frame >= 4) this.frame = 0;
        Game.drawPlayer(
          tileX, tileY, 1, 2, dX, dY, 1, 2,
          this.shadeColor(),
        );
      }
    } else {
      this.frame += 0.1 * delta;
      if (this.frame >= 4) this.frame = 0;
      Game.drawPlayer(
        tileX, tileY, 1, 2, dX, dY, 1, 2,
        this.shadeColor(),
      );
    }

    this.drawArmorLayers(drawnTile.x, drawnTile.y, renderDirection, dX, dY);

    Game.ctx.restore();

    if (needsHelmetCompositing && Game.playerLayerCtx) {
      const ts = GameConstants.TILESIZE;
      const helmetColOffset = divingHelmet ? 16 : 20;
      const helmetTileX = drawnTile.x + helmetColOffset;
      const helmetTileY = drawnTile.y;
      const px = Math.round(dX * ts);
      const py = Math.round(dY * ts);

      const applyMask = () => {
        Game.playerLayerCtx!.globalCompositeOperation = "destination-out";
        Game.playerLayerCtx!.drawImage(
          Game.helmetMaskCanvas!,
          helmetTileX * ts, helmetTileY * ts, ts, ts * 2,
          px, py, ts, ts * 2,
        );
        Game.playerLayerCtx!.globalCompositeOperation = "source-over";
      };

      // First pass: punch holes in base + armor layers at magenta positions
      applyMask();

      // Draw the actual helmet sprite (magenta pixels included at this point)
      Game.drawPlayer(
        helmetTileX, helmetTileY, 1, 2, dX, dY, 1, 2,
        this.shadeColor(),
      );

      // Second pass: erase the magenta pixels that were just drawn as part of the helmet sprite
      applyMask();
    }

    // Reset player layer transform for next frame's clearRect
    Game.playerLayerCtx!.setTransform(1, 0, 0, 1, 0, 0);

    // Restore Game.ctx and blit composite to main canvas with the hurt fade alpha and (separately)
    // the buff outline around the composite silhouette.
    Game.ctx = mainCtx;
    const outlineColor = this.outlineColor();
    const outlineOpacity = this.outlineOpacity();
    const fadeAlpha = this.computeFlashAlpha();

    mainCtx.save();
    mainCtx.setTransform(1, 0, 0, 1, 0, 0);
    // Outline drawn first so it sits behind the composite player on the main canvas.
    if (outlineOpacity > 0) {
      this.blitCompositeOutline(mainCtx, outlineColor, outlineOpacity);
    }
    if (fadeAlpha > 0) {
      mainCtx.globalAlpha = fadeAlpha;
      mainCtx.drawImage(Game.playerLayer!, 0, 0);
      mainCtx.globalAlpha = 1;
    }
    mainCtx.restore();
  };

  private computeFlashAlpha = (): number => {
    if (!this.flashing) return 1;
    // Mirror the rate of the old on/off toggle (period 2 in `flashingFrame` units) but as a
    // smooth cosine fade between 1 and 0.
    return 0.5 + 0.5 * Math.cos(this.flashingFrame * Math.PI);
  };

  private syncOutlineWorkCanvas = () => {
    const layer = Game.playerLayer;
    if (!layer) return;
    if (!this.outlineWorkCanvas) {
      this.outlineWorkCanvas = document.createElement("canvas");
      this.outlineWorkCanvas.width = layer.width;
      this.outlineWorkCanvas.height = layer.height;
      this.outlineWorkCtx = this.outlineWorkCanvas.getContext("2d");
      if (this.outlineWorkCtx) this.outlineWorkCtx.imageSmoothingEnabled = false;
    } else if (
      this.outlineWorkCanvas.width !== layer.width ||
      this.outlineWorkCanvas.height !== layer.height
    ) {
      this.outlineWorkCanvas.width = layer.width;
      this.outlineWorkCanvas.height = layer.height;
      if (this.outlineWorkCtx) this.outlineWorkCtx.imageSmoothingEnabled = false;
    }
  };

  private blitCompositeOutline = (
    mainCtx: CanvasRenderingContext2D,
    color: string,
    opacity: number,
  ) => {
    this.syncOutlineWorkCanvas();
    const layer = Game.playerLayer;
    const out = this.outlineWorkCanvas;
    const oCtx = this.outlineWorkCtx;
    if (!layer || !out || !oCtx) return;

    oCtx.setTransform(1, 0, 0, 1, 0, 0);
    oCtx.globalAlpha = 1;
    oCtx.globalCompositeOperation = "source-over";
    oCtx.clearRect(0, 0, out.width, out.height);

    // Dilate the composite silhouette by 1px in all 8 directions.
    const r = 1;
    for (let dy = -r; dy <= r; dy++) {
      for (let dx = -r; dx <= r; dx++) {
        if (dx === 0 && dy === 0) continue;
        oCtx.drawImage(layer, dx, dy);
      }
    }
    // Subtract the original silhouette to leave just the ring around the player.
    oCtx.globalCompositeOperation = "destination-out";
    oCtx.drawImage(layer, 0, 0);
    // Tint the ring with the outline color.
    oCtx.globalCompositeOperation = "source-in";
    oCtx.globalAlpha = Math.max(0, Math.min(1, opacity));
    oCtx.fillStyle = color;
    oCtx.fillRect(0, 0, out.width, out.height);
    oCtx.globalCompositeOperation = "source-over";
    oCtx.globalAlpha = 1;

    mainCtx.drawImage(out, 0, 0);
  };

  mouseDiagonal = () => {
    const angle = (this.player.inputHandler.mouseAngle() * 180) / Math.PI;
    if (angle > 30 && angle < 60) return true;
    if (angle > 120 && angle < 150) return true;
    if (angle > -150 && angle < -120) return true;
    if (angle > -60 && angle < -30) return true;
    return false;
  };

  private trackMouseLightingDirection = () => {
    if (
      !GameConstants.NARROWED_LIGHTING_FOV ||
      GameConstants.isMobile ||
      !GameConstants.MOVE_WITH_MOUSE
    ) {
      this.lightingDirectionBucket = null;
      return;
    }

    const room = (this.player as any).getRoom
      ? (this.player as any).getRoom()
      : this.player.game.levels[this.player.depth].rooms[this.player.levelID];
    if (!room) {
      this.lightingDirectionBucket = null;
      return;
    }

    const inputHandler = this.player.inputHandler;
    if (inputHandler?.mostRecentMoveInput !== "mouse") {
      this.lightingDirectionBucket = null;
      return;
    }

    const angleDegrees = this.normalizeDegrees(
      (inputHandler.mouseAngle() * 180) / Math.PI,
    );
    const bucket = this.getMouseDirectionBucket(angleDegrees);

    if (bucket === this.lightingDirectionBucket) return;

    this.lightingDirectionBucket = bucket;
    room.updateLighting({ x: this.player.x, y: this.player.y });
  };

  private getMouseDirectionBucket = (angle: number): number => {
    const normalized = this.normalizeDegrees(angle);
    return Math.floor((normalized + 22.5) / 45) % 8;
  };

  private normalizeDegrees = (angle: number): number => {
    const normalized = angle % 360;
    return normalized < 0 ? normalized + 360 : normalized;
  };

  private drawArmorLayers = (
    tileX: number,
    tileY: number,
    renderDirection: Direction,
    dX: number,
    dY: number,
  ) => {
    const player = this.player;
    const shade = this.shadeColor();

    const drawLayer = (overlayTileX: number) => {
      Game.drawPlayer(
        overlayTileX, tileY, 1, 2, dX, dY, 1, 2,
        shade,
      );
    };

    // Chest/back (columns 4–7): chestplate when facing down/right/left, backplate when facing up
    const chestPlate = player.inventory.getChestPlate();
    const backplate = player.inventory.getBackplate();
    if (renderDirection === Direction.UP ? backplate !== null : chestPlate !== null) {
      drawLayer(tileX + 4);
    }

    // Gauntlets (columns 8–11)
    if (player.inventory.getGauntlets() !== null) {
      drawLayer(tileX + 8);
    }

    // Shoulder plates (columns 12–15)
    if (player.inventory.getShoulderPlates() !== null) {
      drawLayer(tileX + 12);
    }
    // Diving helmet (columns 16–19) and helmet (columns 20–23) are drawn by drawPlayerSprite after mask compositing
  };

  drawSmear = () => {
    if (this.player.direction === this.player.lastDirection) return false;
    let t = 100;
    const lastDir = this.player.lastDirection;
    const dir = this.player.direction;
    if (
      (dir === Direction.UP && lastDir === Direction.DOWN) ||
      (dir === Direction.DOWN && lastDir === Direction.UP) ||
      (dir === Direction.LEFT && lastDir === Direction.RIGHT) ||
      (dir === Direction.RIGHT && lastDir === Direction.LEFT)
    )
      t = 150;
    const timeSince = Date.now() - this.player.movement.lastChangeDirectionTime;
    if (timeSince <= t) return true;
    else return false;
  };

  setSmearFrame = () => {
    // All smear frames are on playerset at tileY=8 (row just below the 4 walk rows).
    // x is 0-indexed: 0=down-left, 1=down-right, 2=up-left, 3=up-right.
    // Opposite-direction transitions borrow a walk frame as a mid-phase (tileY = direction * 2).
    let tile = { x: 0, y: 8 };
    const timeSince = Date.now() - this.player.movement.lastChangeDirectionTime;
    const t = 50;

    if (
      (this.player.direction === Direction.UP &&
        this.player.lastDirection === Direction.LEFT) ||
      (this.player.direction === Direction.LEFT &&
        this.player.lastDirection === Direction.UP)
    ) {
      tile.x = 2;
      return tile;
    }
    if (
      (this.player.direction === Direction.UP &&
        this.player.lastDirection === Direction.RIGHT) ||
      (this.player.direction === Direction.RIGHT &&
        this.player.lastDirection === Direction.UP)
    ) {
      tile.x = 3;
      return tile;
    }
    if (
      (this.player.direction === Direction.DOWN &&
        this.player.lastDirection === Direction.RIGHT) ||
      (this.player.direction === Direction.RIGHT &&
        this.player.lastDirection === Direction.DOWN)
    ) {
      tile.x = 1;
      return tile;
    }
    if (
      (this.player.direction === Direction.DOWN &&
        this.player.lastDirection === Direction.LEFT) ||
      (this.player.direction === Direction.LEFT &&
        this.player.lastDirection === Direction.DOWN)
    ) {
      tile.x = 0;
      return tile;
    }
    if (
      this.player.direction === Direction.DOWN &&
      this.player.lastDirection === Direction.UP
    ) {
      if (timeSince < t) tile.x = 2;
      if (timeSince >= t && timeSince < t * 2) { tile.x = 1; tile.y = 6; } // LEFT walk row
      if (timeSince >= t * 2 && timeSince < t * 3) tile.x = 0;
      return tile;
    }
    if (
      this.player.direction === Direction.LEFT &&
      this.player.lastDirection === Direction.RIGHT
    ) {
      if (timeSince < t) tile.x = 1;
      if (timeSince >= t && timeSince < t * 2) { tile.x = 1; tile.y = 0; } // DOWN walk row
      if (timeSince >= t * 2 && timeSince < t * 3) tile.x = 0;
      return tile;
    }
    if (
      this.player.direction === Direction.UP &&
      this.player.lastDirection === Direction.DOWN
    ) {
      if (timeSince < t) tile.x = 1;
      if (timeSince >= t && timeSince < t * 2) { tile.x = 1; tile.y = 4; } // RIGHT walk row
      if (timeSince >= t * 2 && timeSince < t * 3) tile.x = 3;
      return tile;
    }
    if (
      this.player.direction === Direction.RIGHT &&
      this.player.lastDirection === Direction.LEFT
    ) {
      if (timeSince < t) tile.x = 0;
      if (timeSince >= t && timeSince < t * 2) { tile.x = 1; tile.y = 0; } // DOWN walk row
      if (timeSince >= t * 2 && timeSince < t * 3) tile.x = 1;
      return tile;
    }
    return tile;
  };

  draw = (delta: number) => {
    const player = this.player;
    Game.ctx.save();
    this.trackMouseLightingDirection();
    this.updateDrawXY(delta);
    player.drawableY = player.y;
    this.flashingFrame += (delta * 12) / GameConstants.FPS;
    if (!player.dead) {
      Shadow.draw(player.x - this.drawX, player.y - this.drawY, 1, 1);
      //this.drawTileCursor(delta);

      // Hurt flash is now applied as a smooth alpha fade inside drawPlayerSprite via the
      // offscreen composite blit, so always call drawPlayerSprite when the player is alive.
      this.drawPlayerSprite(delta);
    }
    this.drawSpellBeam(delta);
    Game.ctx.restore();
  };

  drawSpellBeam = (delta: number) => {
    Game.ctx.save();

    if (this.player.inventory.getWeapon() instanceof Spellbook) {
      const spellbook = this.player.inventory.getWeapon() as Spellbook;
      spellbook.drawBeams(
        this.player.x - this.drawX,
        this.player.y - this.drawY,
        delta,
      );
    }

    Game.ctx.restore();
  };

  shadeColor = () => {
    const player = this.player;

    if (!GameConstants.CUSTOM_SHADER_COLOR_ENABLED) {
      return "black";
    } else {
      const room = (this.player as any).getRoom
        ? (this.player as any).getRoom()
        : this.player.game.levels[this.player.depth].rooms[this.player.levelID];
      return Utils.rgbToHex(
        room.col[player.x][player.y][0],
        room.col[player.x][player.y][1],
        room.col[player.x][player.y][2],
      );
    }
  };

  drawTopLayer = (delta: number) => {
    Game.ctx.save(); // Save the current canvas state

    this.player.healthBar.draw(
      delta,
      this.player.health,
      this.player.maxHealth,
      this.player.x - this.drawX,
      this.player.y - this.drawY - this.drawZ,
      !this.flashing || Math.floor(this.flashingFrame) % 2 === 0,
      { mana: { current: this.player.mana, max: this.player.maxMana } },
    );

    Game.ctx.restore(); // Restore the canvas state
  };

  private pushingMove: boolean = false;
  private nextMoveIsPush: boolean = false;
  private pushAnimStartMag: number = 1;

  markPushingMove = (): void => {
    // Mark the *next* movement delta as a push (consumed by setNewDrawXY).
    this.nextMoveIsPush = true;
  };

  updateDrawXY = (delta: number) => {
    // Safety: if we're fully stopped, never keep push easing armed.
    if (this.pushingMove && this.doneMoving()) this.pushingMove = false;
    if (!this.doneMoving()) {
      const speed = this.pushingMove
        ? (() => {
            const mag = Math.max(
              Math.abs(this.drawX),
              Math.abs(this.drawY),
              Math.abs(this.drawZ),
            );
            // Capture start magnitude lazily the first frame we animate this push.
            if (this.pushAnimStartMag <= 0.0001) {
              this.pushAnimStartMag = Math.max(0.0001, mag);
            }
            const start = Math.max(0.0001, this.pushAnimStartMag);
            const t = Math.max(0, Math.min(1, 1 - mag / start));
            const tt = t * t; // ease-in
            const slow = GameConstants.PLAYER_PUSH_DRAW_MOVE_SPEED_START;
            const fast = GameConstants.PLAYER_PUSH_DRAW_MOVE_SPEED_END;
            return slow + (fast - slow) * tt;
          })()
        : GameConstants.PLAYER_DRAW_MOVE_SPEED;
      this.drawX *= speed ** delta;
      this.drawY *= speed ** delta;
      this.drawZ *= speed ** delta;
      this.drawX = Math.abs(this.drawX) < 0.01 ? 0 : this.drawX;
      this.drawY = Math.abs(this.drawY) < 0.01 ? 0 : this.drawY;
      this.drawZ = Math.abs(this.drawZ) < 0.01 ? 0 : this.drawZ;
      if (this.doneMoving()) {
        this.pushingMove = false;
        this.pushAnimStartMag = 0;
      }
    }
    if (this.doneHitting()) {
      this.jump(delta);
    }

    if (!this.doneHitting()) {
      this.updateHitXY(delta);
    }

    this.enableSlowMotion();
    GameConstants.ANIMATION_SPEED = this.motionSpeed;
    this.player.updatePushMoveInputLock();
  };

  updateHitXY = (delta: number) => {
    // Use exponential decay like updateDrawXY for stable behavior with variable frame rates
    this.hitX *= 0.7 ** delta;
    this.hitY *= 0.7 ** delta;

    // Clamp values to prevent extreme behavior
    this.hitX = Math.min(Math.max(this.hitX, -1), 1);
    this.hitY = Math.min(Math.max(this.hitY, -1), 1);

    // Snap to zero when values get very small
    if (Math.abs(this.hitX) < 0.01) this.hitX = 0;
    if (Math.abs(this.hitY) < 0.01) this.hitY = 0;
  };

  doneMoving = (): boolean => {
    let EPSILON = 0.01;
    return (
      Math.abs(this.drawX) < EPSILON &&
      Math.abs(this.drawY) < EPSILON &&
      Math.abs(this.drawZ) < EPSILON
    );
  };

  doneHitting = (): boolean => {
    let EPSILON = 0.01;
    return Math.abs(this.hitX) < EPSILON && Math.abs(this.hitY) < EPSILON;
  };

  snapDrawStuff = () => {
    this.drawX = 0;
    this.drawY = 0;
    this.hitX = 0;
    this.hitY = 0;
    this.jumpY = 0;
  };

  setHitXY = (x: number, y: number) => {
    this.hitX = x;
    this.hitY = y;
  };

  drawGUI = (delta: number, transitioning: boolean = false) => {
    Game.ctx.save();
    if (!this.player.dead) {
      //if (this.player.menu.open) this.player.menu.draw();

      if (this.guiHeartFrame > 0) this.guiHeartFrame += delta;
      if (this.guiHeartFrame > 5) {
        this.guiHeartFrame = 0;
      }

      const armor = this.player.inventory.getArmor();

      // Get the quickbar's left edge position
      const quickbarStartX =
        this.player.inventory.getQuickbarStartX() + (armor ? -34 : -24);
      // Convert to tile coordinates
      let heartStartX = quickbarStartX / GameConstants.TILESIZE;

      // Ensure hearts don't go off the left edge of the screen
      if (heartStartX < 0.25) {
        heartStartX = 0.25;
      }

      // On narrow screens, the bottom-left library button can overlap the hearts.
      // Mirror the coin/inventory-button avoidance logic by shifting the hearts right.
      if (GameConstants.WIDTH < 145 && this.player.bookLibrary) {
        const r = this.player.bookLibrary.getLibraryButtonRect();
        const minHeartStartX = (r.x + r.w + 4) / GameConstants.TILESIZE; // +4px padding
        if (heartStartX < minHeartStartX) heartStartX = minHeartStartX;
      }

      const offsetY = GameConstants.WIDTH > 175 ? 0 : -1.25;
      if (!GameConstants.CLEAN_MODE) {
      for (let i = 0; i < this.player.maxHealth; i++) {
        let shake = 0;
        let shakeY = 0;
        if (
          this.player.health <= 1 &&
          this.player.health !== this.player.maxHealth
        ) {
          shake =
            Math.round(Math.sin(Date.now() / 25 / (i + 1)) + i / 2) /
            2 /
            GameConstants.TILESIZE;
          shakeY =
            Math.round(Math.sin(Date.now() / 25 / (i + 2)) + i / 2) /
            2 /
            GameConstants.TILESIZE;
        }
        let frame = this.guiHeartFrame > 0 ? 1 : 0;

        if (i >= Math.floor(this.player.health)) {
          if (
            i == Math.floor(this.player.health) &&
            (this.player.health * 2) % 2 == 1
          ) {
            // draw half heart
            Game.drawFX(
              4,
              2,
              0.75,
              0.75,
              heartStartX + i / 1.5 + shake,
              GameConstants.HEIGHT / GameConstants.TILESIZE -
                1 +
                shakeY +
                offsetY,
              0.75,
              0.75,
            );
          } else {
            Game.drawFX(
              3,
              2,
              0.75,
              0.75,
              heartStartX + i / 1.5 + shake,
              GameConstants.HEIGHT / GameConstants.TILESIZE -
                1 +
                shakeY +
                offsetY,
              0.75,
              0.75,
            );
          }
        } else {
          Game.drawFX(
            frame,
            2,
            0.75,
            0.75,
            heartStartX + i / 1.5 + shake,
            GameConstants.HEIGHT / GameConstants.TILESIZE -
              1 +
              shakeY +
              offsetY,
            0.75,
            0.75,
          );
        }
      }

      // Mana orb (GUI): draw above the heart row, not tied to the floating HealthBar animation.
      this.drawManaOrbGUI(heartStartX, offsetY);

      //this.drawCooldownBar();
      this.drawBreathStatus(quickbarStartX);
      if (armor) armor.drawGUI(delta, this.player.maxHealth, quickbarStartX);
      } // end !CLEAN_MODE
      if (!transitioning) {
        // Draw the library button first so the inventory can draw over it (requested layering).
        if (!GameConstants.CLEAN_MODE) this.player.bookLibrary?.drawLibraryButton(delta);
        this.player.inventory.draw(delta);
      }
      const inventoryOpen = this.player.inventory.isOpen;
      const quickbarOpen =
        this.player.inventory.isPointInQuickbarBounds(
          MouseCursor.getInstance().getPosition().x,
          MouseCursor.getInstance().getPosition().y,
        ).inBounds && !this.player.inventory.isOpen;
      const inVendingMachine =
        this.player.openVendingMachine &&
        VendingMachine.isPointInVendingMachineBounds(
          MouseCursor.getInstance().getPosition().x,
          MouseCursor.getInstance().getPosition().y,
          this.player.openVendingMachine,
        );
      const inInventoryBounds = this.player.inventory.isPointInInventoryBounds(
        MouseCursor.getInstance().getPosition().x,
        MouseCursor.getInstance().getPosition().y,
      ).inBounds;

      const drawFor =
        GameConstants.IN_GAME_HOVER_TEXT_ENABLED &&
        !this.player.menu.open &&
        !this.player.isAnyBookOpen &&
        !inventoryOpen &&
        !quickbarOpen &&
        !this.player.openVendingMachine
          ? "inGame"
          : GameConstants.INVENTORY_HOVER_TEXT_ENABLED &&
              !this.player.menu.open &&
              !this.player.isAnyBookOpen &&
              ((inventoryOpen && inInventoryBounds) || quickbarOpen)
            ? "inventory"
            : GameConstants.VENDING_MACHINE_HOVER_TEXT_ENABLED &&
                !this.player.menu.open &&
                !this.player.isAnyBookOpen &&
                inVendingMachine
              ? "vendingMachine"
              : "none";

      if (
        GameConstants.HOVER_TEXT_ENABLED &&
        !this.player.contextMenu?.open &&
        !this.player.game.isMobile
      ) {
        HoverText.draw(
          delta,
          this.player.x,
          this.player.y,
          this.player.getRoom
            ? this.player.getRoom()
            : this.player.game.levels[this.player.depth].rooms[
                this.player.levelID
              ],
          this.player,
          MouseCursor.getInstance().getPosition().x,
          MouseCursor.getInstance().getPosition().y,
          drawFor,
        );
      }

      // Draw books last so they render above inventory/quickbar.
      if (this.player.bestiary) this.player.bestiary.draw(delta);
      if (this.player.spellbookReader) this.player.spellbookReader.draw(delta);
      if (this.player.bookLibrary) this.player.bookLibrary.draw(delta);
      if (this.player.armoryBook) this.player.armoryBook.draw(delta);
    } else {
      Game.ctx.fillStyle = LevelConstants.LEVEL_TEXT_COLOR;
      const gameStats = statsTracker.getStats();
      const enemies = gameStats.enemies;
      // Count the occurrences of each enemy
      const enemyCounts = enemies.reduce(
        (acc, enemy) => {
          acc[enemy] = (acc[enemy] || 0) + 1;
          return acc;
        },
        {} as Record<string, number>,
      );

      // Create individual lines
      const lines: string[] = [];

      // Line 1: Game Over or slain by
      if (this.player.lastHitBy !== "enemy") {
        lines.push(`You were slain by ${this.player.lastHitBy}.`);
      } else {
        lines.push("Game Over");
      }

      const diedInRoom = (this.player as any).getRoom
        ? (this.player as any).getRoom()
        : this.player.game.levels[this.player.depth].rooms[this.player.levelID];
      lines.push(`Depth reached: ${diedInRoom.depth}`);

      // Line 2: Enemies killed
      lines.push(
        `${Object.values(enemyCounts).reduce(
          (a, b) => a + b,
          0,
        )} enemies killed in total:`,
      );

      // Build enemy lines
      const enemyLines: string[] = [];
      Object.entries(enemyCounts).forEach(([enemy, count]) => {
        enemyLines.push(`${enemy} x${count}`);
      });

      const lineHeight = Game.letter_height + 2;

      // Reserve bottom area for action buttons + feedback button + margins
      const deathButtonH = 14;
      const deathButtonPadX = 12;
      const deathButtonGap = 8;
      const feedbackButtonHeight = 16;
      const bottomMargin = 10;
      const reservedBottomHeight =
        deathButtonH + 8 + feedbackButtonHeight + bottomMargin + 8;

      // Compute available vertical space for content between top margin and reserved bottom
      const topMargin = 20;
      const availableHeight = Math.max(
        0,
        GameConstants.HEIGHT - reservedBottomHeight - topMargin,
      );

      // Fixed header lines (Game Over / Depth / Total)
      const headerLines = lines.length; // currently 3
      const headerHeight = headerLines * lineHeight + lineHeight * 0.5; // slight extra spacing

      // How many enemy lines fit
      const remainingForEnemies = Math.max(0, availableHeight - headerHeight);
      const enemiesPerPageBase = Math.max(
        1,
        Math.floor(remainingForEnemies / lineHeight),
      );

      // Pagination setup
      let enemiesPerPage = enemiesPerPageBase;
      const totalEnemyLines = enemyLines.length;
      // Precompute pages; if more than one page, reserve a row for page indicator by reducing capacity by one
      let totalPages = Math.max(1, Math.ceil(totalEnemyLines / enemiesPerPage));
      if (totalPages > 1) {
        enemiesPerPage = Math.max(1, enemiesPerPageBase - 1);
        totalPages = Math.max(1, Math.ceil(totalEnemyLines / enemiesPerPage));
      }
      this.player.deathScreenPageCount = totalPages;
      const currentPage = Math.min(
        Math.max(0, this.player.deathScreenPageIndex || 0),
        totalPages - 1,
      );
      this.player.deathScreenPageIndex = currentPage;

      const startIdx = currentPage * enemiesPerPage;
      const endIdx = Math.min(totalEnemyLines, startIdx + enemiesPerPage);
      const pageEnemyLines = enemyLines.slice(startIdx, endIdx);

      // Compute starting Y to vertically position the block within available area
      let startY = topMargin;

      // Draw headers
      lines.forEach((line, index) => {
        const textWidth = Game.measureText(line).width;
        const spacing = index <= 1 ? lineHeight * 1.5 : lineHeight;
        Game.fillText(line, GameConstants.WIDTH / 2 - textWidth / 2, startY);
        startY += spacing;
      });

      // Draw enemies for current page
      pageEnemyLines.forEach((line) => {
        const textWidth = Game.measureText(line).width;
        Game.fillText(line, GameConstants.WIDTH / 2 - textWidth / 2, startY);
        startY += lineHeight;
      });

      // Draw page indicator if multiple pages
      if (totalPages > 1) {
        const indicator = `Page ${currentPage + 1}/${totalPages}`;
        const w = Game.measureText(indicator).width;
        const y = GameConstants.HEIGHT - reservedBottomHeight - 6;
        Game.fillText(indicator, GameConstants.WIDTH / 2 - w / 2, y);
      }

      // Build action buttons for death screen
      const replayMgr = (this.player.game as any).replayManager;
      const showReplay =
        GameplaySettings.REPLAY_ON_DEATH && replayMgr?.hasRecordedActions?.();
      type DeathButtonDef = { text: string; action: "replay" | "newgame" };
      const buttonDefs: DeathButtonDef[] = showReplay
        ? [
            { text: "Watch Replay", action: "replay" },
            { text: "New Game", action: "newgame" },
          ]
        : [{ text: "New Game", action: "newgame" }];

      const buttonWidths = buttonDefs.map(
        (b) =>
          Math.round(Game.measureText(b.text).width) + deathButtonPadX * 2,
      );
      let totalBtnW = buttonWidths.reduce((a, w) => a + w, 0);
      totalBtnW += deathButtonGap * (buttonDefs.length - 1);

      const btnStartY = GameConstants.HEIGHT - reservedBottomHeight + 4;
      let bx = Math.round(GameConstants.WIDTH / 2 - totalBtnW / 2);

      const cursor = MouseCursor.getInstance().getPosition();
      const selectedBtn = this.player.deathScreenSelectedButton;
      const usingKeyboard = this.player.deathScreenUsingKeyboard;

      const newRects: Array<{ x: number; y: number; w: number; h: number; action: "replay" | "newgame" }> = [];
      while (this.deathButtonHoverAnims.length < buttonDefs.length) {
        this.deathButtonHoverAnims.push(0);
      }

      for (let i = 0; i < buttonDefs.length; i++) {
        const bw = buttonWidths[i];
        const hovered =
          cursor.x >= bx &&
          cursor.x <= bx + bw &&
          cursor.y >= btnStartY &&
          cursor.y <= btnStartY + deathButtonH;
        const active = usingKeyboard ? selectedBtn === i : hovered;
        const target = active ? 1 : 0;
        this.deathButtonHoverAnims[i] +=
          0.3 * delta * (target - this.deathButtonHoverAnims[i]);
        this.deathButtonHoverAnims[i] = Math.max(
          0,
          Math.min(1, this.deathButtonHoverAnims[i]),
        );

        const growPx = Math.round(3 * this.deathButtonHoverAnims[i]);
        const rx = bx - growPx;
        const ry = btnStartY - growPx;
        const rw = bw + 2 * growPx;
        const rh = deathButtonH + 2 * growPx;

        Game.ctx.fillStyle = active
          ? "rgba(75, 75, 75, 0.7)"
          : "rgba(100, 100, 100, 0.5)";
        Game.ctx.fillRect(rx, ry, rw, rh);

        Game.ctx.fillStyle = "rgba(255, 255, 0, 1)";
        const tw = Game.measureText(buttonDefs[i].text).width;
        const tx = Math.round(rx + (rw - tw) / 2);
        const ty = Math.round(ry + (rh - Game.letter_height) / 2);
        Game.fillText(buttonDefs[i].text, tx, ty);

        newRects.push({
          x: bx,
          y: btnStartY,
          w: bw,
          h: deathButtonH,
          action: buttonDefs[i].action,
        });
        bx += bw + deathButtonGap;
      }
      this.player.deathScreenButtonRects = newRects;

      // Draw feedback button at the very bottom reserved area
      if (this.player.game.feedbackButton) {
        const feedbackY = btnStartY + deathButtonH + 8;

        const textWidth = Game.measureText(
          this.player.game.feedbackButton.text,
        ).width;
        const buttonWidth = textWidth + 10;
        const centeredX = (GameConstants.WIDTH - buttonWidth) / 2;

        this.player.game.feedbackButton.x = centeredX;
        this.player.game.feedbackButton.y = feedbackY;
        this.player.game.feedbackButton.draw();
      }

      // Navigation hint for pagination on desktop
      if (!GameConstants.isMobile && totalPages > 1) {
        const hint = "Use arrow keys to view more";
        const hintWidth = Game.measureText(hint).width;
        const hintY =
          (this.player.game.feedbackButton?.y || GameConstants.HEIGHT - 20) +
          feedbackButtonHeight +
          4;
        if (hintY < GameConstants.HEIGHT - 2) {
          Game.fillText(hint, GameConstants.WIDTH / 2 - hintWidth / 2, hintY);
        }
      }

      if (!this.player.game.hasRecordedStats) {
        // The default value for `lastHitBy` is "enemy", so we compare to that to determine if
        // the player was killed by an enemy
        const gameDurationMs = Date.now() - this.player.game.gameStartTimeMs;
        const inventoryItems = this.player.inventory.items
          .filter((item) => item?.name && item?.stackCount)
          .map((item) => ({
            name: item.name,
            stackSize: item.stackCount,
          }));

        const { createGameState } = require("../game/gameState");

        // Report game stats to Turnarchist backend server
        safeRecordGameStats({
          userId: getOrCreateUserId(),
          xp: gameStats.xp,
          level: gameStats.level,
          gameDurationMs,
          inventory: inventoryItems,
          killedBy: this.player.lastHitBy ?? null,
          enemiesKilled: enemies,
          damageDone: gameStats.damageDone,
          damageTaken: gameStats.damageTaken,
          depthReached: diedInRoom.depth,
          turnsPassed: gameStats.turnsPassed,
          coinsCollected: gameStats.coinsCollected,
          itemsCollected: gameStats.itemsCollected,
          deviceType: getDeviceInfo(),
          sidePathsEntered: gameStats.sidePathsEntered,
          weaponChoice: gameStats.weaponChoice,
          gameState: createGameState(this.player.game),
          gameVersion: this.player.game.version,
          loadedFromSaveFile: this.player.game.loadedFromSaveFile,
        });
        this.player.game.hasRecordedStats = true;
      }
    }

    const game = this.player?.game;
    const cameraOrigin = game?.getWaterOverlayOrigin?.() ?? {
      x: 0,
      y: 0,
    };

    PostProcessor.draw(
      delta,
      this.player?.getRoom()?.underwater ?? false,
      cameraOrigin,
    );
    if (this.hurting) this.drawHurt(delta);

    if (!GameConstants.CLEAN_MODE && this.player.mapToggled === true && !this.player.isAnyBookOpen)
      this.player.map.draw(delta);
    this.drawTileCursor(delta);
    this.drawTargetIndicator(delta);
    this.drawRangedTargetCursor(delta);
    this.player.setCursorIcon();

    //this.drawInventoryButton(delta);
    // Overlay ordering (top-most last):
    // - Bestiary is drawn above inventory earlier in the frame.
    // - Skills menu should appear above bestiary/inventory.
    // - Menu should appear above skills (and everything else).
    // - Context menu should appear above EVERYTHING (including Menu/Skills) so right-click is never hidden.
    this.player.skillsMenu?.draw(delta);
    if (this.player.settingsMenu?.open) this.player.settingsMenu.draw(delta);
    else if (this.player.menu.open) this.player.menu.draw(delta);
    this.player.contextMenu?.draw(delta);
    this.player.replayMenu?.draw(delta);
    this.player.screenMessage?.draw(delta);
    Game.ctx.restore();
  };

  private drawBreathStatus = (quickbarStartX: number) => {
    const helmet = this.player.getEquippedDivingHelmet();
    const barWidth = 64;
    const barHeight = 6;
    const barX = Math.max(8, quickbarStartX - 16);
    const barY = GameConstants.HEIGHT - 28;

    if (helmet) {
      const ratio = Math.max(0, helmet.currentAir / helmet.maxAir);
      Game.ctx.fillStyle = "rgba(8, 20, 32, 0.65)";
      Game.ctx.fillRect(barX, barY, barWidth, barHeight);
      Game.ctx.fillStyle = "#2bd6ff";
      Game.ctx.fillRect(
        barX + 1,
        barY + 1,
        Math.max(0, (barWidth - 2) * ratio),
        barHeight - 2,
      );
      Game.fillTextOutline(
        `Air ${Math.ceil(helmet.currentAir)}/${helmet.maxAir}`,
        barX,
        barY - 2,
        GameConstants.OUTLINE,
        "white",
      );
      return;
    }

    if (!this.player.isDrowning) return;

    const turns = Math.max(0, this.player.getDrowningTurnsUntilDamage());
    Game.fillTextOutline(
      `Drowning ${turns}t`,
      barX,
      barY - 2,
      GameConstants.OUTLINE,
      GameConstants.WARNING_RED,
    );
  };

  drawCooldownBar = () => {
    Game.ctx.save();
    if (this.player.cooldownRemaining > 0) {
      this.player.cooldownRemaining =
        1 -
        (Date.now() - this.player.movement.lastMoveTime) /
          this.player.movement.adjustedCooldown;
    } else this.player.cooldownRemaining = 0;
    const tile = GameConstants.TILESIZE;
    Game.drawFX(
      12 +
        Math.max(
          0,
          Math.min(14, Math.floor(17 * this.player.cooldownRemaining)),
        ),
      2,
      1,
      1,
      0.45,
      GameConstants.HEIGHT / tile - 2.125,
      1,
      1,
    );
    Game.ctx.restore();
  };

  drawHurt = (delta: number) => {
    Game.ctx.save(); // Save the current canvas state
    Game.ctx.globalAlpha = this.hurtAlpha;
    this.hurtAlpha -= (this.hurtAlpha / 10) * delta;
    if (this.hurtAlpha <= 0.01) {
      this.hurtAlpha = 0;
      this.hurting = false;
      this.hurtingShield = false;
    }
    Game.ctx.globalCompositeOperation = "source-over";
    Game.ctx.fillStyle = "#cc3333"; // bright but not fully saturated red
    if (this.hurtingShield) {
      Game.ctx.fillStyle = "#639bff"; // bright but not fully saturated blue
    }

    Game.ctx.fillRect(0, 0, GameConstants.WIDTH, GameConstants.HEIGHT);

    Game.ctx.restore(); // Restore the canvas state
  };

  drawLowHealth = (delta: number) => {
    Game.ctx.save();
    //unused
    if (this.player.health <= 1 && !this.player.dead) {
      // Calculate pulsating alpha for the vignette effect
      const lowHealthAlpha = 0.5; //Math.sin(this.lowHealthFrame / 10) * 0.5 + 0.5;
      Game.ctx.globalAlpha = lowHealthAlpha;
      this.lowHealthFrame += delta;

      const gradientBottom = Game.ctx.createLinearGradient(
        0,
        GameConstants.HEIGHT,
        0,
        (GameConstants.HEIGHT * 2) / 3,
      );

      // Define gradient color stops
      [gradientBottom].forEach((gradient) => {
        gradient.addColorStop(0, "#cc3333"); // Solid red at edges
        gradient.addColorStop(1, "rgba(0, 0, 0, 0)"); // Transparent toward center
      });

      // Draw the gradients
      Game.ctx.globalCompositeOperation = "source-over";

      Game.ctx.fillStyle = gradientBottom;
      Game.ctx.fillRect(0, 0, GameConstants.WIDTH, GameConstants.HEIGHT);

      // Reset composite operation and alpha
      Game.ctx.globalCompositeOperation = "source-over";
      Game.ctx.globalAlpha = 1.0;
    } else {
      this.lowHealthFrame = 0;
    }
    Game.ctx.restore();
  };

  private drawManaOrbGUI = (heartStartX: number, offsetY: number): void => {
    const maxMana = this.player.maxMana;
    if (!Number.isFinite(maxMana) || maxMana <= 0) return;

    const mana = Math.max(0, Math.min(maxMana, this.player.mana));
    const pct = maxMana > 0 ? mana / maxMana : 0;

    const heartsYTile =
      GameConstants.HEIGHT / GameConstants.TILESIZE - 1 + offsetY;

    // Center the orb above the heart row.
    const heartSpan =
      this.player.maxHealth > 1 ? (this.player.maxHealth - 1) / 1.5 : 0;
    const centerXTile = heartStartX + 0.5 * heartSpan;

    const sizePx = 10;
    const x0 = Math.round(centerXTile * GameConstants.TILESIZE - 0.5 * sizePx);
    const y0 = Math.round(heartsYTile * GameConstants.TILESIZE - 14);

    Game.ctx.save();
    Game.ctx.imageSmoothingEnabled = false;
    Game.ctx.imageSmoothingQuality = "low";

    const blue = "#2e7bff";
    const radius = (sizePx - 1) / 2;
    const cx = x0 + radius;
    const cy = y0 + radius;

    // Outline
    Game.ctx.fillStyle = blue;
    for (let py = 0; py < sizePx; py++) {
      for (let px = 0; px < sizePx; px++) {
        const dx = px - radius;
        const dy = py - radius;
        const d = Math.sqrt(dx * dx + dy * dy);
        if (d >= radius - 0.6 && d <= radius + 0.35) {
          Game.ctx.fillRect(x0 + px, y0 + py, 1, 1);
        }
      }
    }

    // Fill (row-by-row, bottom-up)
    const innerBottom = y0 + sizePx - 2;
    const innerTop = y0 + 1;
    const innerH = Math.max(0, innerBottom - innerTop + 1);
    const filledRows = Math.round(pct * innerH);
    const yFillTop = innerBottom - filledRows + 1;

    for (let py = innerTop; py <= innerBottom; py++) {
      if (py < yFillTop) continue;
      for (let px = 1; px < sizePx - 1; px++) {
        const dx = x0 + px - cx;
        const dy = py - cy;
        const d = Math.sqrt(dx * dx + dy * dy);
        if (d <= radius - 1.2) {
          Game.ctx.fillRect(x0 + px, py, 1, 1);
        }
      }
    }

    // Current mana number at bottom-right of orb.
    Game.fillTextOutline(
      String(Math.floor(mana)),
      x0 + sizePx - 6,
      y0 + sizePx - 4,
      "black",
      "white",
    );

    // Turns until active spell is castable; shown above the orb when waiting.
    const weapon = this.player.inventory.weapon;
    const spellbook = weapon instanceof Spellbook ? weapon : null;
    const activeCost = spellbook?.activeSpell?.manaCost ?? null;
    const turnsLeft = activeCost !== null ? Math.max(0, activeCost - mana) : 0;
    if (turnsLeft > 0) {
      Game.fillTextOutline(
        String(turnsLeft),
        x0 + sizePx - 6,
        y0 - 2,
        "black",
        "white",
      );
    }

    Game.ctx.restore();
  };

  heartbeat = () => {
    this.guiHeartFrame = 1;
  };

  /**
   * Draws the tile cursor to the canvas.
   * Added `ctx.save()` at the beginning and `ctx.restore()` at the end
   * to ensure canvas state is preserved.
   */
  drawTileCursor = (delta: number) => {
    if (
      this.player.inventory.isOpen ||
      this.player.menu?.open ||
      this.player.settingsMenu?.open ||
      this.player.skillsMenu?.open ||
      this.player.contextMenu?.open ||
      this.player.inputHandler.mostRecentMoveInput === "keyboard" ||
      GameConstants.isMobile ||
      this.player.rangedTargeting?.active
    )
      return;
    Game.ctx.save(); // Save the current canvas state

    if (
      !this.player.mouseInLine() ||
      !this.player.isMouseAboveFloor() ||
      this.player.isMouseOnPlayerTile()
    )
      return;
    let tileX = 24; //inRange ? 22 : 24;
    let tileY = 5;

    Game.drawFX(
      tileX + Math.floor(HitWarning.frame),
      tileY,
      1,
      1,
      this.player.tileCursor.x + this.player.drawX,
      this.player.tileCursor.y + this.player.drawY,
      1,
      1,
    );

    Game.ctx.restore(); // Restore the canvas state
  };

  drawTargetIndicator = (_delta: number) => {
    const target = this.player.inputHandler.keyboardTarget;
    if (!target || target.dead) return;
    if (this.player.contextMenu?.open) return;

    // Convert world tile coords to screen tile coords (same as tileCursor)
    const offsetX = Math.floor(GameConstants.WIDTH / 2) / GameConstants.TILESIZE;
    const offsetY = Math.floor(GameConstants.HEIGHT / 2) / GameConstants.TILESIZE;
    const screenX = (target.x - this.player.x) + offsetX - 0.5 + this.player.drawX + target.drawX;
    const screenY = (target.y - this.player.y) + offsetY - 0.5 + this.player.drawY + target.drawY;

    Game.drawFX(
      25,
      5,
      1,
      1,
      screenX,
      screenY,
      1,
      1,
    );
  };

  private directionFromAngle = (rad: number): Direction => {
    const deg = (rad * 180) / Math.PI;
    if (deg > -45 && deg <= 45) return Direction.RIGHT;
    if (deg > 45 && deg <= 135) return Direction.DOWN;
    if (deg > -135 && deg <= -45) return Direction.UP;
    return Direction.LEFT;
  };

  drawRangedTargetCursor = (_delta: number) => {
    const rt = this.player.rangedTargeting;
    if (!rt?.active) return;
    if (this.player.inventory?.isOpen) return;
    if (this.player.menu?.open) return;
    if (this.player.settingsMenu?.open) return;
    if (this.player.skillsMenu?.open) return;
    if (this.player.isAnyBookOpen) return;
    if (this.player.inputHandler.isMouseOverUI()) return;

    const offsetX = Math.floor(GameConstants.WIDTH / 2) / GameConstants.TILESIZE;
    const offsetY = Math.floor(GameConstants.HEIGHT / 2) / GameConstants.TILESIZE;
    const screenX = (rt.targetX - this.player.x) + offsetX - 0.5 + this.player.drawX;
    const screenY = (rt.targetY - this.player.y) + offsetY - 0.5 + this.player.drawY;

    // Tile cursor on every pattern tile; checkerboard tiles get the inverted frame.
    const patternTiles = rt.getPatternTiles();
    const tilesToDraw = patternTiles.length > 0 ? patternTiles : [{ x: rt.targetX, y: rt.targetY }];
    for (let i = 0; i < tilesToDraw.length; i++) {
      const pt = tilesToDraw[i];
      const ptScreenX = (pt.x - this.player.x) + offsetX - 0.5 + this.player.drawX;
      const ptScreenY = (pt.y - this.player.y) + offsetY - 0.5 + this.player.drawY;
      Game.drawFX(25, 5, 1, 1, ptScreenX, ptScreenY, 1, 1);
    }

    // Downward-pointing yellow arrow above the target tile — pixel-drawn like the
    // vending-machine / tutorial pointer arrows (drawArrowAtApex "down" style).
    const ts = GameConstants.TILESIZE;
    const now = Date.now();
    const bobPeriod = GameConstants.POINTER_BOB_PERIOD_MS;
    const bobT = Math.sin(((now % bobPeriod) / bobPeriod) * Math.PI * 2);
    const bob = Math.round(bobT * 2); // 2 px bob
    const apx = Math.round((screenX + 0.5) * ts); // horizontal center of tile
    const apy = Math.round((screenY - 1) * ts) - 1 - bob; // apex 1 tile above target, bobs upward
    const sz = GameConstants.POINTER_ARROW_SIZE; // 4 rows → 7 px wide base
    Game.ctx.save();
    Game.ctx.fillStyle = "yellow";
    Game.ctx.globalAlpha = 0.9;
    for (let i = 0; i < sz; i++) {
      const w = 1 + 2 * i;
      Game.ctx.fillRect(apx - (w - 1) / 2, apy - i, w, 1);
    }
    Game.ctx.restore();
  };

  jump = (delta: number) => {
    let j = Math.max(Math.abs(this.drawX), Math.abs(this.drawY));
    let jumpY = Math.abs(Math.sin(j * Math.PI) * this.jumpHeight);
    if (Math.abs(jumpY) < 0.01) jumpY = 0;
    if (jumpY > this.jumpHeight) jumpY = this.jumpHeight;
    this.jumpY = jumpY;
  };
}
