import { Direction, Game } from "../../game";
import { Room } from "../../room/room";
import { astar } from "../../utility/astarclass";
import { HitWarning } from "../../drawable/hitWarning";
import { SpikeTrap } from "../../tile/spiketrap";
import { Coin } from "../../item/coin";
import { Player } from "../../player/player";
import { Item } from "../../item/item";
import { Enemy } from "./enemy";
import { FrogEnemy } from "./frogEnemy";
import { Random } from "../../utility/random";
import { DownLadder } from "../../tile/downLadder";
import { Door } from "../../tile/door";
import { GameConstants } from "../../game/gameConstants";
import { WeaponPoison } from "../../item/usable/weaponPoison";

export class BigFrogEnemy extends Enemy {
  ticks: number;
  frame: number;
  seenPlayer: boolean;
  aggro: boolean;
  targetPlayer: Player;
  drop: Item;
  frameLength: number;
  startFrame: number;
  animationSpeed: number;
  tickCount: number;
  rumbling: boolean;
  jumping: boolean;
  jumpDistance: number;
  halfJumped: boolean;
  static difficulty: number = 1;
  static tileX: number = 37;
  static tileY: number = 24;
  static examineText = "A hulking hopper. Big swings, big reach.";

  constructor(room: Room, game: Game, x: number, y: number, drop?: Item) {
    super(room, game, x, y);
    this.ticks = 0;
    this.frame = 0;
    this.health = 4;
    this.maxHealth = 4;
    this.defaultMaxHealth = 4;
    this.tileX = 37;
    this.tileY = 24;
    this.seenPlayer = false;
    this.aggro = false;
    this.deathParticleColor = "#ffffff";
    this.frameLength = 3;
    this.startFrame = 0;
    this.animationSpeed = 0.1;
    this.tickCount = 0;
    this.jumping = false;
    this.jumpDistance = 1;
    this.drop = drop ? drop : new Coin(this.room, this.x, this.y);
    this.name = "bigfrog";
    this.orthogonalAttack = true;
    this.diagonalAttack = true;
    this.jumpHeight = 2;
    this.imageParticleX = 3;
    this.imageParticleY = 30;
    this.canDestroyOthers = true;
    this.halfJumped = false;
    this.canCrushOthers = true;
    this.dropChance = 1;
    //if (drop) this.drop = drop;
    this.h = 2;
    this.w = 2;
  }

  hit = (): number => {
    return this.damage;
  };

  uniqueKillBehavior = () => {
    if (this.cloned) return;

    const playerResult = this.nearestPlayer();
    const player = playerResult !== false ? playerResult[1] : null;

    // Build the 4 spawn tiles for the 2x2 footprint
    const tiles: { x: number; y: number }[] = [];
    for (let dx = 0; dx < this.w; dx++) {
      for (let dy = 0; dy < this.h; dy++) {
        tiles.push({ x: this.x + dx, y: this.y + dy });
      }
    }

    // Split by manhattan distance == 2 from player
    const list1: { x: number; y: number }[] = []; // distance == 2
    const list2: { x: number; y: number }[] = []; // distance != 2
    for (const tile of tiles) {
      const dist = player
        ? Math.abs(tile.x - player.x) + Math.abs(tile.y - player.y)
        : -1;
      if (dist === 2) list1.push(tile);
      else list2.push(tile);
    }

    const allTiles = [...list1, ...list2];

    // Pick one tile at random to carry the poison drop
    const poisonIdx = Math.floor(Random.rand() * allTiles.length);

    // Spawn all 4 frogs, all waking up instantly
    const spawnedFrogs = allTiles.map((tile, i) => {
      const frog = FrogEnemy.add(this.room, this.game, tile.x, tile.y);
      if (frog && player) {
        (frog as FrogEnemy).seenPlayer = true;
        (frog as FrogEnemy).aggro = true;
        (frog as FrogEnemy).targetPlayer = player;
        (frog as FrogEnemy).skipNextTurns = 1;
      }
      if (i === poisonIdx && frog) {
        (frog as FrogEnemy).drops = [new WeaponPoison(this.room, tile.x, tile.y)];
      }
      return frog;
    });
  };

  poison = () => {};

  behavior = () => {
    this.lastX = this.x;
    this.lastY = this.y;
    if (this.cloned) return;

    this.tileX = 37;
    this.frameLength = 3;
    this.animationSpeed = 0.1;

    if (!this.dead) {
      if (this.handleSkipTurns()) return;
      if (!this.seenPlayer) {
        this.tileX = 37;
        this.lookForPlayer();
      } else if (this.seenPlayer) {
        this.tileX = 37;
        if (this.room.playerTicked === this.targetPlayer) {
          this.alertTicks = Math.max(0, this.alertTicks - 1);
          this.ticks++;
          if (this.ticks % 2 === 1) {
            this.rumbling = true;
            let oldX = this.x;
            let oldY = this.y;
            let disablePositions = Array<astar.Position>();

            let targetPosition = {
              x: this.targetPlayer.x,
              y: this.targetPlayer.y,
            };

            // Build localized disables (avoid scanning the entire room's entities every tick)
            disablePositions = this.buildEntityDisablePositionsLocalized(
              targetPosition,
              (e) => e !== this && !e.destroyable,
            );

            // Account for this enemy's 2x2 footprint when avoiding active spike traps
            for (let xx = this.x - 1; xx <= this.x + this.w; xx++) {
              for (let yy = this.y - 1; yy <= this.y + this.h; yy++) {
                if (
                  this.room.roomArray[xx] &&
                  this.room.roomArray[xx][yy] &&
                  this.room.roomArray[xx][yy] instanceof SpikeTrap &&
                  (this.room.roomArray[xx][yy] as SpikeTrap).on
                ) {
                  // don't walk on active spiketraps
                  disablePositions.push({ x: xx, y: yy } as astar.Position);
                }
              }
            }

            // 2x2-aware jump-over logic
            const px = this.targetPlayer.x;
            const py = this.targetPlayer.y;
            const sharesRow = py >= this.y && py < this.y + this.h;
            const sharesCol = px >= this.x && px < this.x + this.w;

            const isRightAdjacent = sharesRow && px === this.x + this.w; // x + 2
            const isLeftAdjacent = sharesRow && px === this.x - 1;
            const isBelowAdjacent = sharesCol && py === this.y + this.h; // y + 2
            const isAboveAdjacent = sharesCol && py === this.y - 1;

            // Track whether we attempted a jump-over and whether it succeeded
            let triedAdjacentJump = false;
            let performedJump = false;

            const isAreaClear = (
              tx: number,
              ty: number,
              w: number,
              h: number,
            ): boolean => {
              // Precompute occupied tiles once for this check.
              // Only non-destroyable entities should block (matches original behavior).
              const occupied = new Set<string>();
              for (const e of this.room.entities) {
                if (e === this) continue;
                if (e.destroyable) continue;
                const ew = e.w || 1;
                const eh = e.h || 1;
                for (let dx = 0; dx < ew; dx++) {
                  for (let dy = 0; dy < eh; dy++) {
                    occupied.add(`${e.x + dx},${e.y + dy}`);
                  }
                }
              }

              for (let xx = 0; xx < w; xx++) {
                for (let yy = 0; yy < h; yy++) {
                  const ax = tx + xx;
                  const ay = ty + yy;
                  if (!this.room.roomArray[ax] || !this.room.roomArray[ax][ay])
                    return false;
                  const tile = this.room.roomArray[ax][ay];
                  if (
                    tile.isSolid() ||
                    tile.isDoor ||
                    tile instanceof DownLadder
                  )
                    return false;
                  // prevent entity overlap
                  if (occupied.has(`${ax},${ay}`)) return false;
                }
              }
              return true;
            };

            if (isRightAdjacent) {
              triedAdjacentJump = true;
              const tx = px + 1;
              const ty = this.y;
              if (isAreaClear(tx, ty, this.w, this.h)) {
                this.tryMove(tx, ty);
                this.setDrawXY(oldX, oldY);
                if (this.jumping) {
                  this.frame = 8;
                  this.animationSpeed = 1;
                }
                if (this.x > oldX) this.direction = Direction.RIGHT;
                else if (this.x < oldX) this.direction = Direction.LEFT;
                else if (this.y > oldY) this.direction = Direction.DOWN;
                else if (this.y < oldY) this.direction = Direction.UP;
                this.rumbling = false;
                performedJump = true;
                return;
              }
            } else if (isLeftAdjacent) {
              triedAdjacentJump = true;
              const tx = px - this.w;
              const ty = this.y;
              if (isAreaClear(tx, ty, this.w, this.h)) {
                this.tryMove(tx, ty);
                this.setDrawXY(oldX, oldY);
                if (this.jumping) {
                  this.frame = 8;
                  this.animationSpeed = 1;
                }
                if (this.x > oldX) this.direction = Direction.RIGHT;
                else if (this.x < oldX) this.direction = Direction.LEFT;
                else if (this.y > oldY) this.direction = Direction.DOWN;
                else if (this.y < oldY) this.direction = Direction.UP;
                this.rumbling = false;
                performedJump = true;
                return;
              }
            } else if (isBelowAdjacent) {
              triedAdjacentJump = true;
              const tx = this.x;
              const ty = py + 1;
              if (isAreaClear(tx, ty, this.w, this.h)) {
                this.tryMove(tx, ty);
                this.setDrawXY(oldX, oldY);
                if (this.jumping) {
                  this.frame = 8;
                  this.animationSpeed = 1;
                }
                if (this.x > oldX) this.direction = Direction.RIGHT;
                else if (this.x < oldX) this.direction = Direction.LEFT;
                else if (this.y > oldY) this.direction = Direction.DOWN;
                else if (this.y < oldY) this.direction = Direction.UP;
                this.rumbling = false;
                performedJump = true;
                return;
              }
            } else if (isAboveAdjacent) {
              triedAdjacentJump = true;
              const tx = this.x;
              const ty = py - this.h;
              if (isAreaClear(tx, ty, this.w, this.h)) {
                this.tryMove(tx, ty);
                this.setDrawXY(oldX, oldY);
                if (this.jumping) {
                  this.frame = 8;
                  this.animationSpeed = 1;
                }
                if (this.x > oldX) this.direction = Direction.RIGHT;
                else if (this.x < oldX) this.direction = Direction.LEFT;
                else if (this.y > oldY) this.direction = Direction.DOWN;
                else if (this.y < oldY) this.direction = Direction.UP;
                this.rumbling = false;
                performedJump = true;
                return;
              }
            }
            // If adjacent and attempted to jump but destination was blocked, do nothing this turn
            if (triedAdjacentJump && !performedJump) {
              this.rumbling = false;
              return;
            }
            // Build localized path only if we didn't jump over
            const moves = this.searchPathLocalizedCached(
              targetPosition,
              disablePositions,
              { useLastPlayerPos: true, allowOmni: false },
            );
            console.log(moves); //DON'T REMOVE THIS

            if (moves[1]) {
              const wouldHit = (
                player: Player,
                moveX: number,
                moveY: number,
              ) => {
                return (
                  player.x >= moveX &&
                  player.x < moveX + this.w &&
                  player.y >= moveY &&
                  player.y < moveY + this.h
                );
              };

              let hitPlayer = false;
              for (const i in this.game.players) {
                if (this.game.rooms[this.game.players[i].levelID] !== this.room)
                  continue;
                if (
                  wouldHit(this.game.players[i], moves[1].pos.x, moves[1].pos.y)
                ) {
                  const closestTile = this.closestTile(this.game.players[i]);
                  if (!this.shouldSkipAttack()) {
                    this.game.players[i].hurt(this.hit(), this.name, {
                      source: { x: closestTile.x, y: closestTile.y },
                    });
                    this.drawX += 1.5 * (closestTile.x - this.game.players[i].x);
                    this.drawY += 1.5 * (closestTile.y - this.game.players[i].y);
                    if (
                      this.game.players[i] ===
                      this.game.players[this.game.localPlayerID]
                    )
                      this.game.shakeScreen(5 * this.drawX, 5 * this.drawY);
                  }
                  hitPlayer = true;
                }
              }
              if (!hitPlayer) {
                if (moves.length > 1) {
                  let moveX = moves[1].pos.x;
                  let moveY = moves[1].pos.y;
                  this.tryMove(moveX, moveY);
                  this.setDrawXY(oldX, oldY);

                  if (this.jumping) {
                    this.frame = 8;
                    this.animationSpeed = 1;
                  }
                  if (this.x > moveX) this.direction = Direction.RIGHT;
                  else if (this.x < moveX) this.direction = Direction.LEFT;
                  else if (this.y > moveY) this.direction = Direction.DOWN;
                  else if (this.y < moveY) this.direction = Direction.UP;
                }
              }
            }
            this.rumbling = false;
          } else {
            this.makeBigHitWarnings();
            this.rumbling = true;
            this.tileX = 43;
            this.frame = 0;
            this.frameLength = 2;
            this.animationSpeed = 0.2;
          }
        }

        let targetPlayerOffline =
          Object.values(this.game.offlinePlayers).indexOf(this.targetPlayer) !==
          -1;
        if (!this.aggro || targetPlayerOffline) {
          let p = this.nearestPlayer();
          if (p !== false) {
            let [distance, player] = p;
            if (
              distance <= 4 &&
              (targetPlayerOffline ||
                distance < this.playerDistance(this.targetPlayer))
            ) {
              if (player !== this.targetPlayer) {
                this.targetPlayer = player;
                this.facePlayer(player);
                if (player === this.game.players[this.game.localPlayerID])
                  this.alertTicks = 1;
                if (this.ticks % 2 === 0) {
                  this.makeBigHitWarnings();
                }
              }
            }
          }
        }
      }
    }
  };

  jump = (delta: number) => {
    //console.log(`this.drawX, this.drawY: ${this.drawX}, ${this.drawY}`);
    if (this.jumping && !this.cloned) {
      let j = Math.max(Math.abs(this.drawX), Math.abs(this.drawY));
      if (j >= 1) {
        this.jumpDistance = 2;
      }
      this.jumpY =
        Math.sin((j / (this.jumpDistance + 1)) * Math.PI) * this.jumpHeight;
      if (this.jumpY < 0.01 && this.jumpY > -0.01) {
        this.jumpY = 0;
        this.jumpDistance = 1;
      }
      if (this.jumpY > this.jumpHeight) this.jumpY = this.jumpHeight;
    }
  };

  bigEnemyShake = () => {
    if (this.w > 1 || this.h > 1) {
      setTimeout(() => {
        this.game.shakeScreen(0 * this.drawX, 5);
      }, 500);
    }
  };

  makeBigHitWarnings = () => {
    this.makeHitWarnings();
  };

  makeHitWarnings = () => {
    if (this.unconscious || !this.seenPlayer || this.ticks % 2 === 1) return;

    // Explicit target list: range-2 orthogonal from each face + range-1 corner diagonals.
    // Diagonal offsets applied per body tile produce range-1 orthogonal hits on interior
    // edges (e.g. top-left + (1,-1) lands on top-right's above cell), so we enumerate
    // the 12 valid targets directly instead of using the offset-based approach.
    const targets = [
      // Left face (x - 2)
      { tx: this.x - 2, ty: this.y },
      { tx: this.x - 2, ty: this.y + 1 },
      // Right face (x + 3)
      { tx: this.x + 3, ty: this.y },
      { tx: this.x + 3, ty: this.y + 1 },
      // Top face (y - 2)
      { tx: this.x,     ty: this.y - 2 },
      { tx: this.x + 1, ty: this.y - 2 },
      // Bottom face (y + 3)
      { tx: this.x,     ty: this.y + 3 },
      { tx: this.x + 1, ty: this.y + 3 },
      // Corner diagonals
      { tx: this.x - 1, ty: this.y - 1 },
      { tx: this.x + 2, ty: this.y - 1 },
      { tx: this.x - 1, ty: this.y + 2 },
      { tx: this.x + 2, ty: this.y + 2 },
    ];

    for (const { tx, ty } of targets) {
      if (!this.isWithinRoomBounds(tx, ty)) continue;
      if (this.occupiesTile(tx, ty, this.z ?? 0)) continue;
      this.room.hitwarnings.push(
        new HitWarning(this.game, tx, ty, this.x, this.y, true, false, this),
      );
    }
  };

  drawTopLayer = (delta: number) => {
    this.drawableY = this.y;
    this.tickHealthBarHover();

    this.healthBar.draw(
      delta,
      this.health,
      this.maxHealth,
      this.x + 0.5,
      this.y,
      true,
    );
  };

  draw = (delta: number) => {
    if (this.dead) return;
    Game.ctx.save();
    Game.ctx.globalAlpha = this.alpha;
    if (!this.dead) {
      this.updateDrawXY(delta);
      this.frame += this.animationSpeed * delta;
      if (this.frame >= this.frameLength) {
        this.frame = 0;
      }
      let rumbleX = this.rumble(this.rumbling, this.frame).x;
      let rumbleY = this.rumble(this.rumbling, this.frame).y;
      if (this.drawX !== 0 || this.drawY !== 0) {
        this.jumping = true;
      } else {
        this.jumping = false;
      }
      if (this.jumping) {
        if (this.frame < 4) this.frame = 4;
        this.frameLength = 11;
        this.animationSpeed = 0.2;
      } else {
        this.frameLength = 3;
        this.animationSpeed = 0.1;
      }
      if (this.hasShadow) this.drawShadow(delta);
      this.drawMobWithCrush(
        this.tileX +
          (this.tileX !== 59 && !this.rumbling && !this.cloned
            ? Math.floor(this.frame)
            : 0) *
            2,
        this.tileY /*+ this.direction * 2,*/,
        2,
        3,
        this.x + rumbleX - this.drawX,
        this.y - this.drawYOffset - this.drawY - this.jumpY,
        2,
        3,
        this.softShadeColor,
        this.shadeAmount(),
        undefined,
        this.outlineColor(),
        this.outlineOpacity(),
      );
    }
    if (!this.cloned) {
      if (!this.seenPlayer) {
        this.drawSleepingZs(delta, 0.5 * GameConstants.TILESIZE);
      }
      if (this.alertTicks > 0) {
        this.drawExclamation(delta, 0.5 * GameConstants.TILESIZE);
      }
    }
    Game.ctx.restore();
  };
}
